'use strict';
const D=window.STUDIO,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={answers:{},read:[],known:[],drafts:{},checks:{}},storageOK=true;
try{const v=JSON.parse(localStorage.getItem('english-studio-v1')||'null');if(v&&typeof v==='object')state={...state,...v};if(!state.answers||Array.isArray(state.answers))state.answers={};for(const k of ['read','known'])if(!Array.isArray(state[k]))state[k]=[];}catch{storageOK=false}
let session=null,flashOpen=new Set(),vocabGroup='All',search='',writingType='profile';
const iconPaths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 6c-3-2-6-2-10-1v15c4-1 7-1 10 1m0-15c3-2 6-2 10-1v15c-4-1-7-1-10 1V6Z',practice:'m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15v5Z',words:'M4 5h9M8 3v2c0 7-3 10-6 12m2-8c2 4 5 6 9 7m1 5 5-13 5 13m-8-4h7',writing:'M5 3h10l4 4v14H5V3Zm9 0v5h5M8 12h8m-8 4h6',review:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2',arrow:'M5 12h14m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',more:'M5 12h.01M12 12h.01M19 12h.01',close:'m6 6 12 12M6 18 18 6',folder:'M3 7V5h7l2 3h9v12H3V7Z',calendar:'M4 5h16v16H4V5Zm4-3v6m8-6v6M4 11h16',audio:'M4 9h4l5-5v16l-5-5H4V9Zm12-2c3 3 3 7 0 10m3-13c5 5 5 11 0 16',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`}
function lessonProgress(l){const qs=D.questions.filter(q=>q.topic===l.id),done=qs.filter(q=>state.answers[q.id]?.correct).length;return {total:qs.length,done,pct:Math.round(done/qs.length*100)}}
function save(){try{localStorage.setItem('english-studio-v1',JSON.stringify(state))}catch{storageOK=false}$('#save-status').textContent=storageOK?'Guardado en este navegador':'Guardado solo en esta sesión';$('#error-count').textContent=missed().length;const rail=document.querySelector('#rail-progress');if(rail){rail.textContent=state.read.length+' de 8 bloques';document.querySelector('#rail-progress-bar').style.width=(state.read.length/8*100)+'%';}}
function toast(s){$('#toast').textContent=s;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4200)}
function stats(){let a=Object.values(state.answers),tries=a.reduce((s,x)=>s+x.attempts,0),right=a.reduce((s,x)=>s+x.correctAttempts,0);return{done:a.length,tries,right,accuracy:tries?Math.round(right/tries*100):0,mastered:a.filter(x=>x.correct).length}}
function missed(){return D.questions.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct)}
function btn(text,href,secondary=false){return `<a class="btn ${secondary?'secondary':''}" href="${href}">${text}<span aria-hidden="true">↗</span></a>`}
function heading(k,h,p){return `<div class="page-head"><div class="eyebrow">${k}</div><h1>${h}</h1><p>${p}</p></div>`}
function home(){const s=stats(),next=D.lessons.find(l=>!state.read.includes(l.id))||D.lessons[0],n=D.lessons.indexOf(next)+1,percent=Math.round(state.read.length/D.lessons.length*100);return `<div class="dashboard-intro"><div><span class="overline">Tu inglés, un día a la vez</span><h1>Hola, Luis<span class="greeting-dot">.</span></h1><p>Un buen momento para seguir aprendiendo.</p></div><a class="text-link" href="#plan">${icon('calendar')} Ver mi plan de estudio</a></div><div class="dashboard-top"><section class="continue-card"><div class="continue-copy"><div class="course-chip">Unidad 1 <span>·</span> Origins</div><h2>Tu siguiente paso:<br><em>${next.subtitle}</em></h2><p lang="en">${next.desc}</p><div class="actions">${btn(state.read.length?'Continuar estudiando':'Comenzar la unidad','#guide/'+next.id)}<span class="lesson-ref">Bloque ${n} de 8</span></div></div><div class="unit-art" aria-hidden="true"><span class="art-label">ENGLISH / C1</span><span class="art-one">01</span><div class="art-line"></div><span class="art-caption">A little practice.<br>A story of your own.</span></div></section><section class="unit-progress" aria-labelledby="progress-title"><div class="section-kicker">A tu ritmo</div><h2 id="progress-title">Tu progreso</h2><div class="progress-ring" style="--value:${percent}%"><span><b>${percent}%</b><small>de la guía</small></span></div><div class="progress-caption"><strong>${state.read.length} de 8 bloques</strong><span>marcados como estudiados</span></div><a href="#review" class="text-link">Ver mi actividad ${icon('arrow')}</a></section></div><div class="metric-row"><div>${icon('practice')}<span><b>${s.done}<small> / ${D.questions.length}</small></b><span>Ejercicios practicados</span></span></div><div>${icon('check')}<span><b>${s.tries?s.accuracy+'%':'—'}</b><span>Acierto en tus intentos</span></span></div><div>${icon('words')}<span><b>${state.known.length}<small> / 70</small></b><span>Expresiones aprendidas</span></span></div></div><div class="home-grid"><section><div class="section-title"><div><span class="section-kicker">Explora la unidad</span><h2>Tu ruta de aprendizaje</h2></div><span>8 bloques</span></div><div class="lesson-list">${D.lessons.map(l=>{const lp=lessonProgress(l),read=state.read.includes(l.id),current=l.id===next.id;return `<a class="lesson-row ${current?'is-next':''} ${read?'is-read':''}" href="#guide/${l.id}"><span class="lesson-num">${read?icon('check'):l.num}</span><div class="lesson-info"><div class="lesson-title"><h3>${l.subtitle}</h3>${current?'<span class="next-badge">Siguiente</span>':read?'<span class="read-badge">Estudiado</span>':''}</div><p>${l.title}</p></div><span class="lesson-completion"><span>${lp.done}/${lp.total}</span><span class="mini-track"><i style="width:${lp.pct}%"></i></span></span><span class="lesson-arrow">${icon('arrow')}</span></a>`}).join('')}</div></section><aside class="home-aside"><div class="aside-card practice-invite"><span class="aside-symbol">${icon('practice')}</span><span class="section-kicker">Pasa a la acción</span><h3>10 preguntas.<br>Una idea más clara.</h3><p>Mezcla los temas de la unidad y descubre qué necesitas reforzar.</p>${btn('Iniciar práctica rápida','#practice/mixed')}</div><div class="aside-card daily-word"><div class="section-title"><span class="section-kicker">Vocabulario en contexto</span>${icon('words')}</div><h3 class="word" lang="en">a dark horse</h3><p>Alguien que sorprende con un talento inesperado.</p><blockquote lang="en">“I had no idea she played the piano. She’s a dark horse!”</blockquote><a href="#vocab" class="text-link">Explorar las 70 fichas ${icon('arrow')}</a></div>${missed().length?`<a href="#review" class="review-callout">${icon('review')}<span><strong>${missed().length} errores para repasar</strong><small>Una nueva oportunidad de aprender</small></span>${icon('arrow')}</a>`:''}</aside></div>`}
function inline(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\([^)]+\)/g,'$1')}
function markdown(text){
 const lines=String(text).split('\n');let out='',paragraph=[],list=[],listType=null,table=[];
 function closeParagraph(){if(paragraph.length){out+='<p>'+inline(paragraph.join(' '))+'</p>';paragraph=[]}}
 function closeList(){if(list.length){out+='<'+listType+'>'+list.map(v=>'<li>'+inline(v)+'</li>').join('')+'</'+listType+'>';list=[];listType=null}}
 function closeTable(){if(!table.length)return;const rows=table.filter(l=>!/^\|[\s:|\-]+\|?$/.test(l));out+='<div class="table-wrap" role="region" aria-label="Reference table" tabindex="0"><table><thead>'+rows.slice(0,1).map(l=>'<tr>'+l.split('|').slice(1,-1).map(c=>'<th scope="col">'+inline(c.trim())+'</th>').join('')+'</tr>').join('')+'</thead><tbody>'+rows.slice(1).map(l=>'<tr>'+l.split('|').slice(1,-1).map(c=>'<td>'+inline(c.trim())+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';const cells=rows.map(l=>l.split('|').slice(1,-1).map(c=>c.trim()));out+='<dl class="reference-cards">'+cells.slice(1).map(row=>'<div><dt>'+inline(row[0])+'</dt>'+row.slice(1).map((cell,i)=>'<dd><span>'+inline(cells[0][i+1]||'')+'</span>'+inline(cell)+'</dd>').join('')+'</div>').join('')+'</dl>';table=[]}
 const depths=[...String(text).matchAll(/^(#+) /gm)].map(m=>m[1].length),baseDepth=Math.min(...depths,4);let lastHeading=1;
 for(const line of lines){const l=line.trim();if(!l){closeParagraph();closeList();closeTable();continue}if(l.startsWith('|')){closeParagraph();closeList();table.push(l);continue}closeTable();const item=l.match(/^(?:([-*]) |(\d+)\. )(.+)$/);if(item){closeParagraph();const type=item[2]?'ol':'ul';if(listType&&listType!==type)closeList();listType=type;list.push(item[3]);continue}closeList();const h=l.match(/^(#{1,4}) (.+)/);if(h){closeParagraph();const n=Math.min(h[1].length-baseDepth+2,4,lastHeading+1);lastHeading=n;out+='<h'+n+'>'+inline(h[2])+'</h'+n+'>'}else if(l.startsWith('> ')){closeParagraph();out+='<blockquote>'+inline(l.slice(2))+'</blockquote>'}else paragraph.push(l)}closeParagraph();closeList();closeTable();return out;
}
const guideParts={start:()=>D.resources.extra.split('# Reading and evidence')[0],names:()=>D.resources.guide.split('## 1.1')[1].split('### Grammar:')[0].replace(/^ What’s in a name\?/, '# What’s in a name?')+'\n## Reading and evidence\n'+D.resources.extra.split('# Reading and evidence')[1].split('# Personality')[0],continuous:()=> '# The continuous aspect\n\n### Grammar:'+D.resources.guide.split('### Grammar:')[1].split('## 1.2')[0]+'\n## Lookback contrasts\nShe is coming tomorrow: an arrangement. She comes from Osaka: origin. The house was being painted: passive work in progress. I had been working for sixteen hours: duration before a past event. I have had ten days off: a period up to now. I have been having tennis lessons: repeated activity.\n## A useful reminder\nBoth I have lived here for ten years and I have been living here for ten years can be natural. The continuous highlights duration. Follow the context; a single verb can have more than one valid form.',habits:()=> '# What are you like?\n'+D.resources.guide.split('## 1.2 What are you like?')[1].split('## 1.3')[0]+'\n## Lookback vocabulary\nMature: able to disagree respectfully. Perceptive: notices details. Obstinate: refuses to change. Conscientious: responsible and careful. Open-minded: considers alternatives. Inquisitive: curious.\n## Profiles as discussion\n'+D.resources.extra.split('# Personality and habits')[1].split('# Francesco')[0]+'\n## More idioms\n'+idiomGuide(),pictures:()=> '# Picture perfect\n'+D.resources.guide.split('## 1.3 Picture perfect')[1].split('### Vague language')[0],vague:()=> '# Vague language\n'+D.resources.guide.split('### Vague language in conversation')[1].split('## 1.4')[0]+'\n## Patterns to remember\nA couple of + plural noun. Plenty of + noun, without a. Stuff is uncountable: a lot of stuff; pick it up. Around fifty = fifty or so. Sort of and kind of soften a description. Avoid exactly eight-ish.\n## Example\nWe have a couple of things to do, but plenty of time. Let’s meet at about eight. I’ve left some stuff at the hotel; I’ll collect it later.',objects:()=> '# The stories we keep\n'+D.resources.guide.split('## 1.4 Francesco’s Venice')[1].split('## Writing:')[0]+'\n## Francesco’s Venice\n'+D.resources.extra.split('# Francesco’s Venice')[1].split('# Sound')[0],writing:()=> '# Your story, in words\n'+D.resources.guide.split('## Writing:')[1]+'\n## Speaking practice\n'+D.resources.extra.split('# Sound and speaking')[1]};
function idiomGuide(){return D.vocab.filter(x=>x.group==='Idioms').map(x=>`- **${x.term}**: ${x.meaning}. ${x.example}`).join('\n')}
const guideTitles={start:'Before you begin',names:'Names & identity',continuous:'The continuous aspect',habits:'Habits & personality',pictures:'Speculating carefully',vague:'Vague language',objects:'Objects & memories',writing:'Writing & speaking'};
function translationButton(id,label='Ver ayuda en español'){return `<button class="translation-button" type="button" popovertarget="${id}" title="${esc(label)}" aria-label="${esc(label)}" lang="es">ES<span class="sr-only"> · Español</span></button>`}
function spanishHelp(sec,id){return `<div id="${id}" popover class="translation-tooltip" role="dialog" aria-labelledby="${id}-title" lang="es"><div class="translation-header"><span>Ayuda en español</span><button type="button" class="tiny" popovertarget="${id}" popovertargetaction="hide">Cerrar</button></div><h2 id="${id}-title">${esc(sec.title)}</h2><div class="translation-content">${markdown(sec.body)}${sec.rule?`<aside class="rule-box"><span>Regla para recordar</span><p>${inline(sec.rule)}</p></aside>`:''}${sec.examples?sec.examples.map(([en,note])=>`<div class="worked-example"><p lang="en">${esc(en)}</p><p>${esc(note)}</p></div>`).join(''):''}</div></div>`}
function theoryBody(l){const t=D.theory[l.id];return `<div class="lesson-overview"><div class="overview-heading"><span class="section-kicker">Think in English</span>${translationButton('translation-overview','Ver objetivos y método en español')}</div><p>${esc(t.intro)}</p><div class="thinking-method"><strong>Read → notice → use</strong><span>Read the meaning in English. Notice the example. Explain the idea in your own words before checking Spanish.</span></div><h2>By the end, you can</h2><ul class="learning-goals">${t.goals.map(g=>`<li>${icon('check')}<span>${esc(g)}</span></li>`).join('')}</ul><nav class="section-index" aria-label="Sections in this lesson">${t.sections.map((sec,i)=>`<button type="button" data-action="lesson-section" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span>${esc(sec.title)}</button>`).join('')}</nav></div>${spanishHelp({title:'Objetivos y método',body:t.es.intro+'\n\n'+t.es.goals.map(g=>'- '+g).join('\n')+'\n\n**Piensa en inglés:** lee el significado en inglés, observa el ejemplo y explica la idea con tus palabras antes de consultar la traducción.'},'translation-overview')}<div class="theory-sections">${t.sections.map((sec,i)=>`<section class="study-section ${sec.kind||''}" id="theory-section-${i}" aria-labelledby="theory-heading-${i}"><header><span class="section-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><h2 id="theory-heading-${i}" tabindex="-1">${esc(sec.title)}</h2>${translationButton('translation-'+i,'Ver «'+sec.title+'» en español')}</header><div class="theory-body">${markdown(sec.body)}${sec.rule?`<aside class="rule-box"><span>${icon('book')} Remember this pattern</span><p>${inline(sec.rule)}</p></aside>`:''}${sec.examples?`<div class="worked-examples"><h3>Examples in context</h3>${sec.examples.map(([en,note])=>`<div class="worked-example"><p lang="en">${esc(en)}</p><p>${esc(note)}</p></div>`).join('')}</div>`:''}${sec.vocabGroup?`<dl class="theory-vocab">${D.vocab.filter(v=>v.group===sec.vocabGroup).map((v,n)=>`<div><dt><span>${esc(v.term)}</span>${translationButton('idiom-translation-'+n,'Ver «'+v.term+'» en español')}</dt><dd>${esc(sec.definitions[v.term])}<span>${esc(v.example)}</span></dd>${spanishHelp({title:v.term,body:v.meaning+'\n\n'+v.example},'idiom-translation-'+n)}</div>`).join('')}</dl>`:''}</div>${spanishHelp(sec.es,'translation-'+i)}</section>`).join('')}</div>`}
function guide(id='start'){const l=D.lessons.find(l=>l.id===id)||D.lessons[0],idx=D.lessons.indexOf(l),read=state.read.includes(l.id);return heading('Origins · Unit 1 · Lesson '+(idx+1)+' of 8',guideTitles[l.id],D.theory[l.id].intro)+`<div class="mobile-lesson-picker"><label for="lesson-picker">Choose a lesson</label><select id="lesson-picker" name="lesson-picker">${D.lessons.map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${x.num} · ${guideTitles[x.id]}</option>`).join('')}</select></div><div class="study-layout"><nav class="toc" aria-label="Study lessons"><div class="toc-title">Origins · Contents</div>${D.lessons.map(x=>`<a href="#guide/${x.id}" class="${l.id===x.id?'active':''}" ${l.id===x.id?'aria-current="page"':''}><span class="toc-num">${state.read.includes(x.id)?'✓':x.num}</span>${guideTitles[x.id]}</a>`).join('')}<a href="#sources" class="toc-resources">${icon('folder')} Library & answer keys</a></nav><div class="lesson-content"><div class="reader-toolbar"><span>${l.ref}</span><span class="${read?'status-done':'status-pending'}">${read?'✓ Studied':'To study'}</span></div><article class="reader theory-reader" lang="en">${theoryBody(l)}<div class="note">${icon('book')}<span>Understand the rule, notice the example and try the practice. Use an ES button when you need Spanish support.</span></div><div class="reader-actions"><button class="btn ${read?'secondary':''}" data-action="read" data-id="${l.id}">${icon('check')}${read?'Lesson studied':'Mark as studied'}</button>${btn('Practise this lesson','#practice/'+l.id,true)}</div></article><nav class="lesson-pagination" aria-label="Previous and next lessons">${idx>0?`<a href="#guide/${D.lessons[idx-1].id}"><small>Previous</small>${guideTitles[D.lessons[idx-1].id]}</a>`:'<span></span>'}${idx<7?`<a href="#guide/${D.lessons[idx+1].id}"><small>Next ${icon('arrow')}</small>${guideTitles[D.lessons[idx+1].id]}</a>`:`<a href="#practice/mixed"><small>Put it into practice</small>Review Origins</a>`}</nav></div></div>`}
const typeNames={choice:'Selección simple',gap:'Completa la palabra o forma verbal',phrase:'Completa la frase',dialogue:'Completa la conversación',drag:'Arrastra a los espacios',error:'Encuentra y corrige el error',order:'Ordena arrastrando',classify:'Identifica la categoría'};
let slotAnswers=[],pickedToken=null,practiceClock=null,clockInterval=null;
function shuffle(a){return a.map(v=>({v,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.v)}
function clearClock(){if(clockInterval)clearInterval(clockInterval);clockInterval=null}
function startSession(topic='all',type='all'){clearClock();practiceClock=null;let qs=topic==='errors'?missed():D.questions.filter(q=>topic==='all'||topic==='mixed'||q.topic===topic);qs=shuffle(qs.filter(q=>type==='all'||q.type===type));if(topic==='mixed')qs=qs.slice(0,10);session={topic,type,qs,index:0,checked:false,correct:0};slotAnswers=[];pickedToken=null;}
function expected(q){return q.blanks?q.blanks.map(b=>b.answer).join(' / '):Array.isArray(q.answer)?q.answer.join(' / '):q.answer}
function isBoard(q){return q.type==='drag'||q.type==='order'}
function slotCount(q){return q.type==='order'?q.options.length:q.blanks.length}
function slotButton(q,i){const token=slotAnswers[i],filled=Number.isInteger(token);return `<button type="button" class="drop-slot ${filled?'filled':''}" data-action="place-token" data-slot="${i}" ${filled?'draggable="true" data-token="'+token+'"':''} aria-label="Espacio ${i+1}${filled?': '+esc(q._options[token])+'. Pulsa para devolverlo al banco.':': vacío. Selecciona una ficha y colócala aquí.'}"><small aria-hidden="true">${i+1}</small><span>${filled?esc(q._options[token]):'Coloca aquí'}</span></button>`}
function boardContents(q){return q.type==='order'?`<div class="sentence-slots" lang="en">${Array.from({length:slotCount(q)},(_,i)=>slotButton(q,i)).join('')}</div>`:`<div class="cloze-text" lang="en">${q.template.split('___').map((part,i)=>esc(part)+(i<q.blanks.length?slotButton(q,i):'')).join('')}</div>`}
function tokenBank(q){return q._options.map((word,i)=>`<button type="button" class="token ${pickedToken===i?'picked':''}" data-action="pick-token" data-token="${i}" draggable="true" aria-pressed="${pickedToken===i}" ${slotAnswers.includes(i)?'disabled':''}>${esc(word)}</button>`).join('')}
function blankMarkup(q,i){const b=q.blanks[i];return `<span class="inline-blank"><label class="blank-label" for="blank-${i}">Espacio ${i+1}${b.cue?' · '+esc(b.cue):''}</label><input id="blank-${i}" name="blank-${i}" class="blank-input" autocomplete="off" autocapitalize="off" spellcheck="false" required aria-describedby="blank-result-${i}" placeholder="Completa…"><span class="blank-result" id="blank-result-${i}"></span></span>`}
function questionFields(q){if(['choice','classify'].includes(q.type))return `<fieldset class="choice-fieldset"><legend>Selecciona una de las ${q._options.length} opciones</legend><div class="options">${q._options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${esc(o)}" required><span><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span>${esc(o)}</span></label>`).join('')}</div></fieldset>`;
if(isBoard(q))return `<p class="exercise-instruction" id="drag-help">Arrastra cada ficha a su espacio. También puedes <b>seleccionar una ficha y pulsar su destino</b> con ratón, móvil o teclado. Pulsa una ficha colocada para devolverla.</p><div id="drag-board" aria-describedby="drag-help">${boardContents(q)}</div><div class="bank-heading"><span>Fichas disponibles${q.type==='drag'?' · sobran opciones':''}</span><button type="button" class="tiny" data-action="clear-tokens">Vaciar respuesta</button></div><div id="word-bank" class="tokens" lang="en">${tokenBank(q)}</div><p id="placement-status" class="placement-status" role="status">Selecciona o arrastra una ficha para empezar.</p>`;
if(q.type==='dialogue'){let i=0;return `<p class="exercise-instruction">Completa cada turno siguiendo las pistas. Escribe solo lo que falta.</p><div class="conversation">${q.turns.map(t=>`<div class="conversation-turn"><span class="speaker" aria-label="Persona ${esc(t.speaker)}">${esc(t.speaker)}</span><div lang="en">${t.text.split('___').map((part,n,parts)=>esc(part)+(n<parts.length-1?blankMarkup(q,i++):'')).join('')}</div></div>`).join('')}</div>`}
return `${q.cue?`<div class="form-cue"><span>Pista de forma</span><strong>${esc(q.cue)}</strong></div>`:''}<label for="answer">${q.type==='error'?'Escribe la oración completa corregida':q.type==='phrase'?'Escribe la frase que falta':'Escribe solo la palabra o forma que falta'}</label><input class="answer-input" id="answer" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" required placeholder="Tu respuesta…">`}
function practice(topic='all'){if(!session||session.topic!==topic)startSession(topic);const q=session.qs[session.index];const head=heading(topic==='errors'?'Repaso de errores':'Práctica interactiva · Origins',topic==='errors'?'Los errores también enseñan.':'Pon a prueba lo aprendido.','Completa, conversa, arrastra o elige. Cada respuesta incluye una explicación.');const filters=`<div class="filter-control practice-filters"><div><label for="topic">Tema</label><select id="topic" name="topic">${[['all','Toda la unidad'],['mixed','Sesión mixta · 10 preguntas'],...D.lessons.map(x=>[x.id,x.subtitle]),['errors','Solo errores']].map(([v,n])=>`<option value="${v}" ${v===topic?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="exercise-type">Tipo de ejercicio</label><select id="exercise-type" name="exercise-type"><option value="all">Todos los tipos</option>${Object.entries(typeNames).map(([k,v])=>`<option value="${k}" ${session.type===k?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="time-limit">Tiempo por pregunta</label><select id="time-limit" name="time-limit">${[[0,'Sin límite de tiempo'],[45,'45 segundos'],[90,'90 segundos'],[180,'3 minutos']].map(([v,n])=>`<option value="${v}" ${Number(state.practiceSeconds||0)===v?'selected':''}>${n}</option>`).join('')}</select></div><button class="btn secondary" data-action="restart">${icon('review')} Nueva sesión</button></div>`;
if(!session.qs.length)return head+filters+`<div class="empty"><h2>No hay ejercicios pendientes aquí.</h2><p>Prueba otro tema o tipo de ejercicio. Tus errores quedarán disponibles para el repaso.</p></div>`;
if(!q)return head+filters+`<div class="empty"><div class="eyebrow">SESIÓN COMPLETADA</div><h2>${session.correct} de ${session.qs.length} respuestas correctas</h2><p>Las preguntas con solución consultada o tiempo agotado quedan pendientes en tu repaso.</p><div class="actions"><button class="btn" data-action="restart">Otra sesión</button>${btn('Repasar errores','#review',true)}</div></div>`;
q._options=shuffle(q.options||[]);
return head+filters+`<div class="practice-layout"><div><div class="session-heading"><span>Pregunta <strong>${session.index+1}</strong> de ${session.qs.length}</span><span>${session.correct} ${session.correct===1?'correcta':'correctas'} en esta sesión</span></div><section class="question-card" aria-labelledby="question-title"><div class="question-meta"><span>${typeNames[q.type]}</span><span class="topic-tag">${D.lessons.find(l=>l.id===q.topic).subtitle}</span></div><div class="progress" style="margin-bottom:25px"><span style="width:${session.index/session.qs.length*100}%"></span></div><div id="question-clock" class="question-clock" hidden></div><h2 id="question-title">${esc(q.prompt)}</h2><form id="exercise-form">${questionFields(q)}<div id="feedback" aria-live="polite"></div><div class="question-foot"><button class="btn" id="check-btn" type="submit">Comprobar respuesta <span aria-hidden="true">→</span></button><button class="btn secondary" type="button" data-action="hint">${icon('spark')} Pista</button><button class="btn secondary" type="button" data-action="solution">Consultar solución</button><span class="counter">${session.index+1} / ${session.qs.length}</span></div></form></section><p class="correction-note">La corrección ignora mayúsculas y puntuación y reconoce contracciones comunes. Usa las pistas para completar la forma esperada; puede haber otras respuestas válidas en contextos abiertos.</p></div><aside class="practice-aside"><div class="coach-card"><span class="aside-symbol">${icon('spark')}</span><h3>Aprender está en el porqué.</h3><ol><li>Intenta resolverlo sin apuntes.</li><li>Si dudas, pide una pista.</li><li>Lee la explicación y crea tu propio ejemplo.</li></ol><a class="text-link" href="#guide/${q.topic}">Consultar este tema ${icon('arrow')}</a></div><div class="session-note">${icon('review')}<p>El tiempo es opcional. Puedes pausarlo o quitarlo. Si se agota, verás la corrección y la pregunta quedará para repasar.</p></div><a href="#review" class="text-link">Ir a mi repaso ${icon('arrow')}</a></aside></div>`}
function normalize(s){return String(s).toLowerCase().replace(/[’‘]/g,"'").replace(/\bi'm\b/g,'i am').replace(/\bit's\b/g,'it is').replace(/\bwe've\b/g,'we have').replace(/\bi've\b/g,'i have').replace(/\bshe's\b/g,'she is').replace(/\bhe's\b/g,'he is').replace(/\bdon't\b/g,'do not').replace(/\bhaven't\b/g,'have not').replace(/\bisn't\b/g,'is not').replace(/\baren't\b/g,'are not').replace(/\bwasn't\b/g,'was not').replace(/\bweren't\b/g,'were not').replace(/\bcan't\b/g,'cannot').replace(/[.,!?;:"']/g,'').replace(/\s+/g,' ').trim()}
function matches(answer,value,alternatives=[]){return [answer,...alternatives].some(x=>normalize(x)===normalize(value))}
function blankResults(q,a){const values=Array.isArray(a)?a:String(a||'').split(' / ');return q.blanks.map((b,i)=>matches(b.answer,values[i]||'',b.alternatives||[]))}
function judge(q,a){return q.blanks?blankResults(q,a).every(Boolean):(Array.isArray(q.answer)?q.answer:[q.answer,...(q.alternatives||[])]).some(x=>normalize(x)===normalize(a))}
function readAnswer(){const q=session.qs[session.index];if(isBoard(q)){const values=Array.from({length:slotCount(q)},(_,i)=>Number.isInteger(slotAnswers[i])?q._options[slotAnswers[i]]:'');return q.type==='order'?values.join(' '):values}if(q.blanks)return q.blanks.map((b,i)=>$('#blank-'+i)?.value.trim()||'');return new FormData($('#exercise-form')).get('answer')||''}
function completeAnswer(q,a){return isBoard(q)?Array.from({length:slotCount(q)},(_,i)=>Number.isInteger(slotAnswers[i])).every(Boolean):q.blanks?a.every(v=>v.trim()):String(a).trim().length>0}
function finishQuestion(mode='answer'){if(!session||session.checked)return;const q=session.qs[session.index],answer=readAnswer(),correct=mode==='answer'&&judge(q,answer);clearClock();const old=state.answers[q.id]||{attempts:0,correctAttempts:0},last=Array.isArray(answer)?answer.map(v=>v||'(sin responder)').join(' / '):answer||'(sin responder)';state.answers[q.id]={correct,attempts:old.attempts+1,correctAttempts:(old.correctAttempts||0)+(correct?1:0),last:mode==='solution'?'Solución consultada':mode==='timeout'?'Tiempo agotado · '+last:last};session.checked=true;if(correct)session.correct++;save();
const statuses=q.blanks?blankResults(q,answer):[];if(q.blanks)q.blanks.forEach((b,i)=>{const field=$('#blank-'+i),message=$('#blank-result-'+i);if(field){field.setAttribute('aria-invalid',String(!statuses[i]));field.classList.add(statuses[i]?'is-correct':'is-wrong')}if(message)message.textContent=statuses[i]?'✓ Correcto':'Respuesta: '+b.answer;});
const title=mode==='timeout'?'Tiempo agotado · sigue aprendiendo con la corrección':mode==='solution'?'Solución consultada · queda para repasar':correct?'✓ Correcto. Bien razonado.':'Todavía no. Revisa la explicación.';
$('#feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${title}</strong>${q.blanks?`<ol class="blank-corrections">${q.blanks.map((b,i)=>`<li><b>Espacio ${i+1} · ${statuses[i]?'✓ Correcto':'Por revisar'}</b><span>Tu respuesta: <span lang="en">${esc(answer[i]||'Sin responder')}</span></span><span>Forma esperada: <strong lang="en">${esc(b.answer)}</strong></span></li>`).join('')}</ol>`:correct?'':`<p><b>Respuesta esperada:</b> <span lang="en">${esc(expected(q))}</span></p>`}<p>${esc(q.why)}</p>${q.type==='error'&&!correct?'<p>Si tu reformulación también es válida, compárala con el modelo.</p>':''}</div>`;
$('#exercise-form').querySelectorAll('input,.token,.drop-slot,[data-action=hint],[data-action=solution],[data-action=clear-tokens]').forEach(el=>{el.disabled=true;el.draggable=false});$('#check-btn').disabled=false;$('#check-btn').textContent=session.index===session.qs.length-1?'Ver resultado →':'Siguiente pregunta →';$('#check-btn').focus({preventScroll:true});const score=document.querySelector('.session-heading')?.lastElementChild;if(score)score.textContent=session.correct+(session.correct===1?' correcta':' correctas')+' en esta sesión';paintClock();}
function check(e){e.preventDefault();if(session.checked){next();return}if(practiceClock?.paused){toast('Reanuda el tiempo para continuar o elige Sin límite de tiempo.');return}if(practiceClock&&Date.now()>=practiceClock.deadline){finishQuestion('timeout');return}const q=session.qs[session.index],answer=readAnswer();if(!completeAnswer(q,answer)){$('#feedback').innerHTML='<div class="note">Completa todos los espacios antes de comprobar. Puedes pedir una pista si la necesitas.</div>';document.querySelector('.drop-slot:not(.filled),input:invalid')?.focus();return}finishQuestion();}
function next(){clearClock();practiceClock=null;session.index++;session.checked=false;slotAnswers=[];pickedToken=null;refreshPractice();$('#main').focus()}
function refreshPractice(){clearClock();$('#main').innerHTML=practice(session.topic);mountPractice()}
function renderBoard(focusSelector){const q=session.qs[session.index];$('#drag-board').innerHTML=boardContents(q);$('#word-bank').innerHTML=tokenBank(q);$('#placement-status').textContent=pickedToken!==null?'Ficha seleccionada: '+q._options[pickedToken]+'. Pulsa su destino.':slotAnswers.filter(Number.isInteger).length+' de '+slotCount(q)+' espacios completados.';if(focusSelector)document.querySelector(focusSelector)?.focus({preventScroll:true})}
function placeToken(token,slot){if(!session||session.checked||practiceClock?.paused)return;const q=session.qs[session.index];if(!isBoard(q)||!Number.isInteger(token)||token<0||token>=q._options.length||!Number.isInteger(slot)||slot<0||slot>=slotCount(q))return;const from=slotAnswers.indexOf(token),displaced=slotAnswers[slot];if(from>=0)slotAnswers[from]=displaced;slotAnswers[slot]=token;pickedToken=null;renderBoard('[data-slot="'+slot+'"]')}
function mountPractice(){clearClock();if(!session||session.checked||!session.qs[session.index]||!$('#exercise-form'))return;const seconds=Number(state.practiceSeconds||0);if(!seconds){practiceClock=null;return}practiceClock={deadline:Date.now()+seconds*1000,paused:false,remaining:seconds*1000,warned:false};paintClock();clockInterval=setInterval(tickClock,250)}
function tickClock(){if(!practiceClock||!session||session.checked)return;if(!practiceClock.paused){practiceClock.remaining=Math.max(0,practiceClock.deadline-Date.now());if(!practiceClock.remaining){finishQuestion('timeout');return}if(practiceClock.remaining<=10000&&!practiceClock.warned){practiceClock.warned=true;toast('Quedan 10 segundos. Puedes pausar o quitar el tiempo.')}}const node=$('#clock-value');if(node)node.textContent=formatTime(practiceClock.remaining);}
function formatTime(ms){const s=Math.ceil(ms/1000);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function paintClock(){const box=$('#question-clock');if(!box)return;box.hidden=!practiceClock;if(!practiceClock)return;box.innerHTML=`<div><span>${session.checked?'Pregunta terminada':practiceClock.paused?'Tiempo en pausa':'Tiempo restante'}</span><b id="clock-value" role="timer" aria-live="off">${formatTime(practiceClock.remaining)}</b></div>${session.checked?'':`<div class="clock-actions"><button class="tiny" type="button" data-action="pause-clock">${practiceClock.paused?'Reanudar':'Pausar'}</button><button class="tiny" type="button" data-action="remove-clock">Quitar tiempo</button></div>`}`;box.classList.toggle('is-paused',Boolean(practiceClock.paused));}
function toggleClock(){if(!practiceClock||session.checked)return;if(!practiceClock.paused&&Date.now()>=practiceClock.deadline){finishQuestion('timeout');return}if(practiceClock.paused){practiceClock.paused=false;practiceClock.deadline=Date.now()+practiceClock.remaining}else{practiceClock.remaining=Math.max(0,practiceClock.deadline-Date.now());practiceClock.paused=true}lockPaused();paintClock();document.querySelector('[data-action=pause-clock]')?.focus({preventScroll:true});toast(practiceClock.paused?'Tiempo en pausa. Reanuda para responder.':'Tiempo reanudado.')}
function lockPaused(){const q=session.qs[session.index],paused=Boolean(practiceClock?.paused);$('#exercise-form')?.querySelectorAll('input,button').forEach(el=>{el.disabled=paused||Boolean(el.dataset.action==='pick-token'&&slotAnswers.includes(Number(el.dataset.token)))});}
function removeClock(){clearClock();practiceClock=null;state.practiceSeconds=0;save();const select=$('#time-limit');if(select)select.value='0';if(!session.checked)lockPaused();paintClock();toast('Puedes continuar sin límite de tiempo.')}
function vocab(){let vs=D.vocab.filter(v=>(vocabGroup==='All'||v.group===vocabGroup)&&(v.term+' '+v.meaning+' '+v.example).toLowerCase().includes(search.toLowerCase()));return heading('Vocabulario · 70 expresiones','Tu colección de palabras.','Aprende cada expresión en contexto. Intenta recordar el significado antes de revelar la ficha.')+`<label for="vocab-search">Buscar una palabra, significado o ejemplo</label><input id="vocab-search" name="vocab-search" class="search-box" value="${esc(search)}" placeholder="Por ejemplo: name, hábitos, inherit…" type="search" autocomplete="off"><div class="filters">${['All',...new Set(D.vocab.map(v=>v.group))].map(g=>`<button class="chip ${vocabGroup===g?'active':''}" data-action="vocab-group" aria-pressed="${vocabGroup===g}" data-id="${g}">${g==='All'?'Todas · 70':g}</button>`).join('')}</div><p id="vocab-summary" style="font-size:12px">${vs.length} ${vs.length===1?'ficha':'fichas'} · ${state.known.length} marcadas como aprendidas. El audio, si está disponible, usa la voz sintética de tu navegador.</p><div id="vocab-cards" class="vocab-grid">${!vs.length?'<p class="empty">No encontramos esa palabra. Prueba una búsqueda más corta.</p>':''}${vs.map(v=>{let id=D.vocab.indexOf(v);return `<article class="vocab-card"><div class="vocab-card-top"><small>${v.group}</small><span class="vocab-state">${state.known.includes(id)?'✓ Aprendida':''}</span></div><h2 lang="en">${esc(v.term)}</h2>${flashOpen.has(id)?`<p>${esc(v.meaning)}</p><p class="example" lang="en">“${esc(v.example)}”</p>`:'<p class="recall-prompt">Antes de mirar, intenta usar esta expresión en una frase.</p>'}<div class="actions"><button class="tiny" data-action="flip" data-index="${id}" aria-expanded="${flashOpen.has(id)}">${flashOpen.has(id)?'Ocultar':'Ver significado'}</button><button class="tiny" data-action="speak" data-index="${id}" aria-label="Escuchar ejemplo de ${esc(v.term)}">${icon('audio')}<span>Escuchar</span></button><button class="tiny" data-action="known" aria-pressed="${state.known.includes(id)}" data-index="${id}">${state.known.includes(id)?'✓ Aprendida':'Ya la sé'}</button></div></article>`}).join('')}</div>`}
const tasks={profile:{title:'A personal profile',range:[150,200],prompt:'Write a 150–200-word profile for a class website. Include your background, interests, a specific experience or achievement, and your current goal.',checks:['Presento mi origen y contexto.','Incluyo intereses o habilidades con detalles.','Desarrollo una experiencia o logro concreto.','Explico mi objetivo actual.','El tono es cercano y adecuado a mi clase.']},object:{title:'A treasured object',range:[120,160],prompt:'Describe an object in 120–160 words: its origin, physical details, a specific memory and why it matters today. Include one continuous form and one past-habit structure.',checks:['Explico qué es y de dónde viene.','Incluyo detalles físicos concretos.','Cuento un recuerdo específico.','Explico por qué importa hoy.','Uso una forma continua y un hábito pasado.']},speaking:{title:'Speak, notice, repeat',range:[0,0],prompt:'Choose one task below. Speak aloud, then write a transcript or notes. Read it again to improve accuracy and range.',checks:['Expreso una idea, una razón y un ejemplo.','Uso las estructuras solicitadas.','Apoyo mis especulaciones en detalles observables.','Identifico una mejora y repito la intervención.']}};
function wordCount(s){return (s.trim().match(/\b[\p{L}\p{N}]+(?:[’'-][\p{L}\p{N}]+)*\b/gu)||[]).length}
function writing(){const t=tasks[writingType];return heading('Writing & speaking','Dale forma a tus ideas.','Escribe, comprueba la estructura y revisa tu borrador. Tus textos se guardan en este navegador.')+`<div class="tabs">${Object.entries(tasks).map(([k,v])=>`<button class="chip ${k===writingType?'active':''}" data-action="writing-tab" aria-pressed="${k===writingType}" data-id="${k}">${v.title}</button>`).join('')}</div><div class="writing-layout"><section class="panel"><h2 lang="en">${t.title}</h2><p lang="en">${t.prompt}</p>${writingType==='speaking'?`<div class="speaking-prompt"><b>Elige una intervención</b><ol><li>Names · 2 min: tu nombre, apodo y primeras impresiones.</li><li>Habits · 2 min: usa tend to, keep + -ing y used to / would.</li><li>Portrait · 90 s: observa un retrato propio, formula tres especulaciones y usa una expresión imprecisa.</li></ol><p>Grábate con tu dispositivo si quieres. Este espacio revisa tu transcripción; no analiza audio.</p></div>`:''}<label for="draft">${writingType==='speaking'?'Transcripción o notas':'Tu borrador en inglés'}</label><textarea id="draft" name="draft" autocomplete="off" placeholder="Start your story here…">${esc(state.drafts[writingType]||'')}</textarea><div class="actions" style="justify-content:space-between;margin:12px 0"><span class="muted" id="word-count" style="font-size:12px">${wordCount(state.drafts[writingType]||'')} palabras${t.range[1]?' · objetivo '+t.range.join('–'):''}</span><button class="btn" data-action="analyze">Revisar borrador →</button></div><div id="writing-feedback" aria-live="polite"></div></section><aside><div class="panel"><h2>Antes de darlo por listo</h2><ul class="checklist">${t.checks.map((c,i)=>`<li><label><input type="checkbox" data-check="${writingType}-${i}" ${state.checks[writingType+'-'+i]?'checked':''}>${c}</label></li>`).join('')}</ul><p style="font-size:11px">La lista es tu autoevaluación. La revisión automática detecta algunos patrones, longitud y organización; no certifica nivel C1 ni evalúa todo el significado.</p></div><div class="note"><b>Una buena revisión tiene tres pasos.</b><br>Primero el mensaje, después la gramática y por último la naturalidad. Lee tu texto en voz alta.</div><details class="panel"><summary>Ver modelos y guía</summary>${markdown(writingType==='object'?guideParts.objects():D.resources.personal.split('## Stage 3:')[1]?.split('## Stage 4:')[0]||guideParts.writing())}</details></aside></div>`}
function analyze(){let text=$('#draft').value.trim(),count=wordCount(text),t=tasks[writingType];if(!text){toast('Escribe un borrador para poder revisarlo.');return}let notes=[];if(t.range[1])notes.push(count<t.range[0]?`Añade detalles: tienes ${count} palabras; el objetivo es ${t.range.join('–')}.`:count>t.range[1]?`Recorta repeticiones: tienes ${count} palabras; el objetivo es ${t.range.join('–')}.`:`✓ Extensión dentro del objetivo: ${count} palabras.`);const paragraphs=text.split(/\n\s*\n/).filter(Boolean).length;notes.push(paragraphs<2?'Organización: separa el texto en párrafos con funciones claras.':`✓ Has separado el texto en ${paragraphs} párrafos. Revisa que cada uno desarrolle una idea.`);
const rules=[[/\b(?:am|is|are|was|were)\s+(?:knowing|owning|belonging)\b/i,'Revisa los verbos de estado: know, own y belong normalmente se usan en simple.'],[/\bprone to\s+(?:forget|make|leave|spend)\b/i,'Después de prone to usa -ing: prone to forgetting / making / leaving / spending.'],[/\bkeeps? to\b/i,'Para repetición usa keep + -ing: keep practising.'],[/\b(?:many stuffs|stuffs)\b/i,'Stuff es incontable: a lot of stuff, sin -s.'],[/\ba plenty of\b/i,'Usa plenty of, sin a.'],[/\ba couple (?!of\b)\w+/i,'Comprueba a couple of + sustantivo plural.'],[/\bexactly\b.{0,15}\b\w+-ish\b/i,'Evita combinar exactly con -ish.'],[/\bsince \d+ (?:years|months|days|hours)\b/i,'Para una duración usa for; since requiere un punto de inicio.']];let hits=rules.filter(([r])=>r.test(text));notes.push(...hits.map(([,m])=>m));if(!hits.length)notes.push('No se detectaron los errores concretos que comprueba este sistema. Aún conviene revisar el resto de la gramática.');
if(writingType==='object'){notes.push(/\b(?:used to|would)\b/i.test(text)?'✓ Se detecta una posible estructura de hábito pasado; comprueba su uso.':'Añade un hábito pasado, por ejemplo: We used to play together.');notes.push(/\b(?:am|is|are|was|were|been)\s+\w+ing\b/i.test(text)?'✓ Se detecta una posible forma continua; explica qué significado tiene.':'Incluye una forma continua relevante al contexto.');}
if(writingType==='profile')notes.push(/\b(?:goal|aim|hope|improv|learning|studying|look forward)\w*\b/i.test(text)?'Se detecta vocabulario de objetivos: verifica que expresas tu meta con claridad.':'Revisa si has explicado tu objetivo actual de manera explícita.');
$('#writing-feedback').innerHTML='<div class="feedback"><strong>Revisión orientativa · reglas locales</strong><ul>'+notes.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ul><p>No se envía el texto a ningún servicio de IA. Para valorar ideas, tono y alternativas válidas, solicita una revisión a tu tutor.</p></div>'}
function review(){const ms=missed(),s=stats();return heading('Tu actividad','Cada intento te hace avanzar.','Una respuesta fallida queda pendiente hasta que la resuelvas. El porcentaje global conserva todos tus intentos.')+`<div class="results"><div><b>${s.mastered}</b><span>resueltos en el último intento</span></div><div><b>${ms.length}</b><span>errores pendientes</span></div><div><b>${s.tries}</b><span>intentos acumulados</span></div><div><b>${s.tries?s.accuracy+'%':'—'}</b><span>acierto global</span></div></div>${ms.length?`<div class="actions" style="margin-bottom:25px">${btn('Practicar mis errores','#practice/errors')}${btn('Volver a la guía','#guide',true)}</div><div class="review-list">${ms.map(q=>`<article class="review-item"><small>${D.lessons.find(l=>l.id===q.topic).subtitle}</small><h3 style="margin:8px 0">${esc(q.prompt)}</h3><p>Tu respuesta: ${esc(state.answers[q.id].last)}</p><details><summary>Ver explicación y respuesta</summary><p><strong>${esc(expected(q))}</strong></p><p>${esc(q.why)}</p></details></article>`).join('')}</div>`:`<div class="empty"><h2>${s.done?'Todo revisado. Sigue ampliando.':'Tu cuaderno de errores está listo.'}</h2><p>${s.done?'No tienes errores pendientes. Prueba otro bloque o una sesión mixta.':'Practica primero. Aquí aparecerán las preguntas que necesites reforzar, junto con su explicación.'}</p>${btn('Practicar ahora','#practice')}</div>`}<div class="note">Tu progreso pertenece a este navegador. Puedes descargar una copia y restaurarla en otro dispositivo.</div><div class="actions"><button class="btn secondary" data-action="export">Descargar progreso</button><label class="btn secondary file-import">Importar progreso<input type="file" id="import-progress" accept="application/json" aria-label="Importar progreso"></label></div>`}
function plan(){return heading('A LITTLE EVERY DAY','Una unidad. Siete días.','Dedica unos 20–30 minutos diarios. Repite los bloques que necesiten más tiempo.')+`<div class="panel"><ol class="plan">${[['Nombres y vocabulario','Explica cinco expresiones y crea ejemplos propios.'],['Aspecto continuo','Responde los ejercicios y explica cada elección.'],['Hábitos y personalidad','Describe tus hábitos durante dos minutos.'],['Especulación y lenguaje impreciso','Describe un retrato con evidencia y cautela.'],['Perfil personal','Redacta y revisa 150–200 palabras.'],['Objetos y recuerdos','Escribe 120–160 palabras sobre un objeto.'],['Recuperación y repaso','Repite tus errores sin apuntes y revisa el Lookback.']].map(([a,b])=>`<li><div><b>${a}</b><p style="margin:3px 0">${b}</p></div></li>`).join('')}</ol>${btn('Empezar por la guía','#guide')}</div>`}
function sources(resource){if(resource&&D.resources[resource])return heading('THE STUDY LIBRARY','Tu material de referencia.','Contenido del material de estudio ya disponible en este proyecto.')+`<div class="actions" style="margin-bottom:20px">${btn('Todos los recursos','#sources',true)}<button class="btn secondary" data-action="print">Imprimir</button></div><article class="reader" lang="en">${markdown(D.resources[resource])}</article>`;return heading('THE STUDY LIBRARY','Todo tu material, a mano.','Guías y respuestas del proyecto, con referencias a las páginas impresas del libro.')+`<div class="panel source-links">${[['guide','Guía de estudio completa'],['extra','Lead-in, lectura, pronunciación y material complementario'],['answers','Solucionario explicado del libro · pp. 6–17, 129 y 148'],['lookback','Lookback · repaso de la p. 18'],['practice','Práctica original · lectura, speaking y writing'],['personal','Actividad de perfil personal · modelo de Luis']].map(([k,n])=>`<a href="#sources/${k}">${n} <span aria-hidden="true">↗</span></a>`).join('')}<a href="My_Godmothers_Mandolin.pdf" target="_blank" rel="noopener">Actividad: My Godmother’s Mandolin ↗</a><a href="Unit_1_Follow_Up_Activity.pdf" target="_blank" rel="noopener">Actividad de seguimiento de la unidad 1 ↗</a><a href="unit-1-study-pack.pdf" target="_blank" rel="noopener">Descargar guía y práctica en PDF ↗</a><a href="unit-1-textbook-answer-key.pdf" target="_blank" rel="noopener">Descargar solucionario en PDF ↗</a><a href="unit-1-lookback-answer-key.pdf" target="_blank" rel="noopener">Descargar Lookback en PDF ↗</a></div><div class="note"><b>Alcance y fuentes.</b> Basado en el PDF de la unidad 1, nivel XI C1 (16 páginas escaneadas), la guía, prácticas y solucionarios del proyecto; más el suplemento de la unidad 2 con las páginas 18 y 158. Los ejercicios interactivos son práctica adaptada y original.<br><br><b>Audio y vídeo pendientes.</b> No están disponibles las grabaciones oficiales ni el vídeo. El sitio no asigna respuestas a tareas que requieren escucharlos. La lectura y el vocabulario de Francesco’s Venice sí se pueden estudiar. Los perfiles de personalidad se usan para discusión, no para diagnosticar a una persona.</div>`}
function render(){const [rawPage,id]=location.hash.slice(1).split('/');const page=rawPage||'home';clearClock();if(page!=='practice'){session=null;practiceClock=null;}if(page==='writing'&&tasks[id])writingType=id;const names={home:'Inicio',guide:'Guía de estudio',practice:'Práctica',vocab:'Vocabulario',writing:'Writing & speaking',review:'Mi repaso',sources:'Biblioteca',plan:'Plan de estudio'};const title=document.querySelector('#current-page');if(title)title.textContent=names[page]||'Inicio';document.body.dataset.page=page||'home';document.querySelector('[data-action=open-menu]')?.classList.toggle('active',['writing','review','sources','plan'].includes(page));document.querySelectorAll('[data-nav]').forEach(a=>{let active=a.dataset.nav===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#main').innerHTML=page==='guide'?guide(id):page==='practice'?practice(id||'all'):page==='vocab'?vocab():page==='writing'?writing():page==='review'?review():page==='plan'?plan():page==='sources'?sources(id):home();save();if(page==='practice')mountPractice();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{const d=document.querySelector('#navigation-dialog');if(d?.open)d.close();render();$('#main').focus()});
document.addEventListener('submit',e=>{if(e.target.id==='exercise-form')check(e)});
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,i=+b.dataset.index;
if(a==='lesson-section'){const title=document.querySelector('#theory-heading-'+i);title?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});title?.focus({preventScroll:true});return}if(a==='open-menu'){document.querySelector('#navigation-dialog').showModal();b.setAttribute('aria-expanded','true');return}if(a==='close-menu'){document.querySelector('#navigation-dialog').close();return}
if(a==='read'){state.read=state.read.includes(id)?state.read.filter(x=>x!==id):[...state.read,id];save();const scrollPosition=window.scrollY;render();window.scrollTo(0,scrollPosition);document.querySelector('[data-action=read]')?.focus({preventScroll:true});toast(state.read.includes(id)?'Bloque marcado como estudiado.':'Bloque pendiente de estudio.');}
if(a==='restart'){startSession($('#topic')?.value||session?.topic||'all',$('#exercise-type')?.value||session?.type||'all');refreshPractice();return}
if(a==='pause-clock'){toggleClock();return}if(a==='remove-clock'){removeClock();return}
if(a==='hint'){if(!session||session.checked||practiceClock?.paused)return;const q=session.qs[session.index];$('#feedback').innerHTML=`<div class="note"><b>Pista</b><p>${q.cue?esc(q.cue):q.type==='error'?'Busca un problema de estructura, preposición o forma verbal.':q.type==='order'?'Busca primero el sujeto, después el auxiliar y el verbo.':q.type==='dialogue'?'Lee la pregunta, la respuesta y la pista de cada espacio antes de elegir la forma verbal.':q.type==='drag'?'Lee lo que aparece antes y después del espacio. Comprueba el patrón y el significado.':'Compara el contexto y el significado, además de la forma.'}</p><a href="#guide/${q.topic}">Consultar la teoría de este bloque →</a></div>`;return}
if(a==='solution'){if(!session||session.checked||practiceClock?.paused)return;finishQuestion(practiceClock&&Date.now()>=practiceClock.deadline?'timeout':'solution');return}
if(['pick-token','place-token','clear-tokens'].includes(a)){if(!session||session.checked||practiceClock?.paused)return;if(a==='pick-token'){const n=Number(b.dataset.token);pickedToken=pickedToken===n?null:n;renderBoard('[data-action=pick-token][data-token="'+n+'"]')}if(a==='place-token'){const slot=Number(b.dataset.slot);if(pickedToken!==null)placeToken(pickedToken,slot);else{slotAnswers[slot]=undefined;renderBoard('[data-slot="'+slot+'"]')}}if(a==='clear-tokens'){slotAnswers=[];pickedToken=null;renderBoard();document.querySelector('#word-bank button')?.focus({preventScroll:true})}return}
if(a==='vocab-group'){vocabGroup=id;$('#main').innerHTML=vocab()}if(a==='flip'){flashOpen.has(i)?flashOpen.delete(i):flashOpen.add(i);$('#main').innerHTML=vocab();document.querySelector('[data-action=flip][data-index="'+i+'"]')?.focus({preventScroll:true})}
if(a==='known'){state.known=state.known.includes(i)?state.known.filter(v=>v!==i):[...state.known,i];save();$('#main').innerHTML=vocab();document.querySelector('[data-action=known][data-index="'+i+'"]')?.focus({preventScroll:true})}
if(a==='speak'){if(!('speechSynthesis'in window)){toast('Tu navegador no ofrece síntesis de voz. Lee el ejemplo en voz alta.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(D.vocab[i].example);u.lang='en-GB';u.rate=.85;u.onerror=()=>toast('No hay voz disponible. Puedes leer el ejemplo en la ficha.');speechSynthesis.speak(u)}
if(a==='writing-tab'){writingType=id;location.hash='writing/'+id;$('#main').innerHTML=writing()}if(a==='analyze')analyze();if(a==='print')window.print();
if(a==='export'){const blob=new Blob([JSON.stringify({version:1,state},null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='english-studio-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Copia de progreso descargada.');}
});
document.addEventListener('change',async e=>{if(e.target.id==='lesson-picker'){location.hash='guide/'+e.target.value;return}if(['topic','exercise-type'].includes(e.target.id)){const topic=$('#topic').value,type=$('#exercise-type').value;startSession(topic,type);if(location.hash!=='#practice/'+topic)location.hash='practice/'+topic;else refreshPractice()}if(e.target.id==='time-limit'){const seconds=Number(e.target.value);state.practiceSeconds=[0,45,90,180].includes(seconds)?seconds:0;save();if(!session.checked){lockPausedAfterTimeChange();mountPractice()}return}if(e.target.dataset.check){state.checks[e.target.dataset.check]=e.target.checked;save()}if(e.target.id==='import-progress'){try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error();const p=JSON.parse(await f.text());if(p.version!==1||!p.state||!p.state.answers||!Array.isArray(p.state.read)||!Array.isArray(p.state.known))throw Error();if(!window.confirm('¿Reemplazar el progreso actual por esta copia?'))return;state={answers:p.state.answers,read:p.state.read.filter(x=>D.lessons.some(l=>l.id===x)),known:p.state.known.filter(x=>Number.isInteger(x)&&x>=0&&x<D.vocab.length),drafts:p.state.drafts||{},checks:p.state.checks||{}};save();session=null;render();toast('Progreso restaurado.')}catch{toast('No se pudo importar. Elige una copia JSON de English Studio.')}}});
document.addEventListener('input',e=>{if(e.target.id==='draft'){state.drafts[writingType]=e.target.value;save();$('#word-count').textContent=wordCount(e.target.value)+' palabras'+(tasks[writingType].range[1]?' · objetivo '+tasks[writingType].range.join('–'):'')}if(e.target.id==='vocab-search'){search=e.target.value;const tmp=document.createElement('div');tmp.innerHTML=vocab();$('#vocab-cards').innerHTML=tmp.querySelector('#vocab-cards').innerHTML||'<p class="empty">No encontramos esa palabra. Prueba una búsqueda más corta.</p>';$('#vocab-summary').textContent=tmp.querySelector('#vocab-summary').textContent;}});
document.querySelector('#navigation-dialog')?.addEventListener?.('close',()=>document.querySelector('[data-action=open-menu]')?.setAttribute('aria-expanded','false'));
function lockPausedAfterTimeChange(){practiceClock=null;lockPaused()}
document.addEventListener('dragstart',e=>{const token=e.target.closest('[draggable=true][data-token]');if(!token||!session||session.checked||practiceClock?.paused){e.preventDefault();return}e.dataTransfer.setData('text/plain',token.dataset.token);e.dataTransfer.effectAllowed='move';document.body.classList.add('dragging-token');});
document.addEventListener('dragover',e=>{const slot=e.target.closest('.drop-slot');if(slot&&session&&!session.checked&&!practiceClock?.paused){e.preventDefault();e.dataTransfer.dropEffect='move';slot.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{const slot=e.target.closest('.drop-slot');if(slot&&!slot.contains(e.relatedTarget))slot.classList.remove('drag-over')});
document.addEventListener('drop',e=>{const slot=e.target.closest('.drop-slot');if(!slot)return;e.preventDefault();const raw=e.dataTransfer.getData('text/plain');if(/^\d+$/.test(raw))placeToken(Number(raw),Number(slot.dataset.slot));document.body.classList.remove('dragging-token')});
document.addEventListener('dragend',()=>{document.body.classList.remove('dragging-token');document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'))});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')tickClock()});
window.EnglishStudio={normalize,judge,wordCount,stats,blankResults};render();
